{
  "aggregate_id": "DEF-NRS-484A-280::tow_car",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The vehicle definition excludes devices moved by human power, preventing the class from satisfying the motor-vehicle requirement."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "Passenger-carrying design neither establishes nor rules out alteration and exclusive towing or vehicle-assistance use."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person, not the motor vehicle required by the definition."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "Commercial mass or licensing does not determine whether a vehicle satisfies either qualifying exclusive-use alternative."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The motor-vehicle definition expressly excludes electric bicycles, while a tow car must be a motor vehicle."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The motor-vehicle definition expressly excludes electric scooters, while a tow car must be a motor vehicle."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation does not establish or preclude exclusive towing or assistance to other vehicles."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "A fire-fighting function does not rule out exclusive assistance to other vehicles, including fighting vehicle fires."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The moped contract does not determine whether the vehicle is exclusively used to render assistance to other vehicles."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "Motor-vehicle membership alone neither establishes nor rules out the additional exclusive-use requirements."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "Wheel configuration and astride riding do not determine whether a motorcycle is exclusively used to assist other vehicles."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official-service kind and identifying livery or equipment do not determine whether either exclusive-use alternative is satisfied."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person rather than the motor vehicle required by the definition."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than a motor vehicle."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The motor-vehicle definition requires operation other than upon rails, which excludes the on-track equipment described by the contract."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "Designation for carrying school children and jurisdictional markings do not establish that every member fails the exclusive towing or vehicle-assistance requirements."
    },
    {
      "class": "ru.taxicab",
      "verdict": "underdetermined",
      "reason": "Being a marked passenger vehicle for hire does not itself rule out exclusive towing or assistance to other vehicles."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "The contract's bus types, passenger-vehicle configuration and livery do not establish incompatibility with both qualifying exclusive-use alternatives."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "The contract encompasses drawn vehicles and combinations without settling whether a member satisfies the motor-vehicle and exclusive-use requirements."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "The contract's public-transit service requirement does not establish that every member is incompatible with exclusive assistance to other vehicles."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "A goods-carrying body does not determine whether the vehicle has been altered for exclusive towing or is exclusively used to assist other vehicles."
    }
  ]
}

